mkdeclfn! {
# [doc = " Creates a \"fork-join\" scope `s` with FIFO order, and invokes the"] # [doc = " closure with a reference to `s`. This closure can then spawn"] # [doc = " asynchronous tasks into `s`. Those tasks may run asynchronously with"] # [doc = " respect to the closure; they may themselves spawn additional tasks"] # [doc = " into `s`. When the closure returns, it will block until all tasks"] # [doc = " that have been spawned into `s` complete."] # [doc = ""] # [doc = " This is just like `scope_fifo()` except the closure runs on the same thread"] # [doc = " that calls `in_place_scope_fifo()`. Only work that it spawns runs in the"] # [doc = " thread pool."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " If a panic occurs, either in the closure given to `in_place_scope_fifo()` or in"] # [doc = " any of the spawned jobs, that panic will be propagated and the"] # [doc = " call to `in_place_scope_fifo()` will panic. If multiple panics occurs, it is"] # [doc = " non-deterministic which of their panic values will propagate."] # [doc = " Regardless, once a task is spawned using `scope.spawn_fifo()`, it will"] # [doc = " execute, even if the spawning task should later panic. `in_place_scope_fifo()`"] # [doc = " returns once all spawned jobs have completed, and any panics are"] # [doc = " propagated at that point."] pub fn in_place_scope_fifo < 'scope , OP , R > (op : OP) -> R where OP : FnOnce (& ScopeFifo < 'scope >) -> R , { do_in_place_scope_fifo (None , op) }
}